                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: groupFilters[filter.id]?.classFilter?.length > 0 ? 600 : 400
                }}
              >
                Class {groupFilters[filter.id]?.classFilter?.length > 0 && `(${groupFilters[filter.id]?.classFilter?.length})`}
              </Button>
            </Dropdown>

            <Button 
              type={groupFilters[filter.id]?.directFilter ? "primary" : "default"}
              size="small"
              onClick={() => setGroupFilters(prev => ({
                ...prev,
