                  ...prev[filter.id],
                  directFilter: !prev[filter.id]?.directFilter
                }
              }))}
            >
              Direct Only
            </Button>

            <Dropdown 
              overlay={renderSourcesDropdownForFilter("group", filter.id)}
              trigger={['click']}
            >
              <Button 
                type={groupFilters[filter.id]?.sourceFilter?.sources?.length > 0 ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: groupFilters[filter.id]?.sourceFilter?.sources?.length > 0 ? 600 : 400
                }}
              >
                Sources {groupFilters[filter.id]?.sourceFilter?.sources?.length > 0 && `(${groupFilters[filter.id]?.sourceFilter?.sources?.length})`}
              </Button>
            </Dropdown>

            <Dropdown 
              overlay={renderAirlinesDropdownForFilter("group", filter.id)}
              trigger={['click']}
            >
              <Button 
                type={groupFilters[filter.id]?.airlinesFilter?.airlines?.length > 0 ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: groupFilters[filter.id]?.airlinesFilter?.airlines?.length > 0 ? 600 : 400
                }}
              >
                Airlines {groupFilters[filter.id]?.airlinesFilter?.airlines?.length > 0 && `(${groupFilters[filter.id]?.airlinesFilter?.airlines?.length})`}
              </Button>
            </Dropdown>

            <Dropdown 
              overlay={renderPointsDropdownForFilter("group", filter.id)}
              trigger={['click']}
            >
              <Button 
                type={groupFilters[filter.id]?.pointsFilter ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: groupFilters[filter.id]?.pointsFilter ? 600 : 400
                }}
              >
                Points {groupFilters[filter.id]?.pointsFilter && `(${groupFilters[filter.id]?.pointsFilter[0].toLocaleString()}-${groupFilters[filter.id]?.pointsFilter[1].toLocaleString()})`}
              </Button>
            </Dropdown>

            <Button 
              type="text" 
              icon={<DeleteOutlined />} 
              size="small"
              style={{ marginLeft: 'auto', color: '#ff4d4f' }}
              onClick={() => deleteFilter(filter.id)}
            />
          </div>
        );
      } else if (filter.type === 'segment') {
        return (
          <div key={filter.id} style={{ 
            display: 'flex', 
            gap: '8px', 
            alignItems: 'center',
            marginBottom: '8px'
          }}>
            <span style={{ 
              fontWeight: 600, 
              marginRight: '4px',
              fontSize: '14px'
            }}>
              Segment-based Filter
            </span>
            <span style={{ whiteSpace: 'nowrap' }}>for</span>
            <Dropdown 
              overlay={renderSegmentsDropdownSimple(filter.id)}
              trigger={['click']}
            >
              <Button 
                type={segmentFilters[filter.id]?.segments?.length > 0 ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: segmentFilters[filter.id]?.segments?.length > 0 ? 600 : 400
                }}
              >
                Segments {segmentFilters[filter.id]?.segments?.length > 0 && `(${segmentFilters[filter.id]?.segments?.length})`}
              </Button>
            </Dropdown>
            <span style={{ whiteSpace: 'nowrap' }}>:</span>

            <Dropdown 
              overlay={renderClassDropdownForFilter("segment", filter.id)}
              trigger={['click']}
            >
              <Button 
                type={segmentFilters[filter.id]?.classFilter?.length > 0 ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: segmentFilters[filter.id]?.classFilter?.length > 0 ? 600 : 400
                }}
              >
                Class {segmentFilters[filter.id]?.classFilter?.length > 0 && `(${segmentFilters[filter.id]?.classFilter?.length})`}
              </Button>
            </Dropdown>

            <Button 
              type={segmentFilters[filter.id]?.directFilter ? "primary" : "default"}
              size="small"
              onClick={() => setSegmentFilters(prev => ({
                ...prev,
                [filter.id]: {
                  ...prev[filter.id],
                  directFilter: !prev[filter.id]?.directFilter
                }
              }))}
            >
              Direct Only
            </Button>

            <Dropdown 
              overlay={renderSourcesDropdownForFilter("segment", filter.id)}
              trigger={['click']}
            >
              <Button 
                type={segmentFilters[filter.id]?.sourceFilter?.sources?.length > 0 ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
