                }}
              >
                Sources {segmentFilters[filter.id]?.sourceFilter?.sources?.length > 0 && `(${segmentFilters[filter.id]?.sourceFilter?.sources?.length})`}
              </Button>
            </Dropdown>

            <Dropdown 
              overlay={renderAirlinesDropdownForFilter("segment", filter.id)}
              trigger={['click']}
            >
              <Button 
                type={segmentFilters[filter.id]?.airlinesFilter?.airlines?.length > 0 ? "primary" : "default"}
                size="small"
                icon={<DownOutlined />}
                style={{ 
                  fontWeight: segmentFilters[filter.id]?.airlinesFilter?.airlines?.length > 0 ? 600 : 400
                }}
              >
                Airlines {segmentFilters[filter.id]?.airlinesFilter?.airlines?.length > 0 && `(${segmentFilters[filter.id]?.airlinesFilter?.airlines?.length})`}
              </Button>
            </Dropdown>

            <Dropdown 
              overlay={renderPointsDropdownForFilter("segment", filter.id)}
