      }}>
        <div style={{ padding: '4px 12px 8px', borderBottom: '1px solid #f0f0f0' }}>
          <Radio.Group
            value={currentFilter.originFilter.mode}
            onChange={e => setGroupFilters(prev => ({
              ...prev,
              [filterId]: {
                ...prev[filterId],
                originFilter: {
                  ...prev[filterId].originFilter,
                  mode: e.target.value
                }
              }
            }))}
            style={{ display: 'flex', gap: '8px' }}
          >
            <Radio.Button 
              value="include" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Include
            </Radio.Button>
            <Radio.Button 
              value="exclude" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Exclude
            </Radio.Button>
          </Radio.Group>
        </div>
        <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
          <Input
            placeholder="Search origin airports/groups..."
            value={originSearchText}
            onChange={e => setOriginSearchText(e.target.value)}
            size="small"
            allowClear
            onClick={e => e.stopPropagation()}
          />
        </div>
        <div style={{ 
          maxHeight: '400px', 
          overflowY: 'auto',
          padding: '8px 0'
        }}>
          {filteredOptions.map(option => (
            <div 
              key={option.code} 
              style={{ 
                padding: '4px 12px',
                cursor: 'pointer'
              }}
            >
              <Checkbox
                checked={currentFilter.originFilter.airports.includes(option.code)}
                onChange={e => {
                  const isChecked = e.target.checked;
                  setGroupFilters(prev => ({
                    ...prev,
                    [filterId]: {
                      ...prev[filterId],
                      originFilter: {
                        ...prev[filterId].originFilter,
                        airports: isChecked 
                          ? [...prev[filterId].originFilter.airports, option.code]
                          : prev[filterId].originFilter.airports.filter(a => a !== option.code)
                      }
                    }
                  }));
                }}
              >
                <div style={{ display: 'flex', flexDirection: 'column', width: '390px' }}>
                  <span style={{ fontWeight: 500 }}>{option.code}</span>
                  <span style={{ 
                    fontSize: '12px', 
                    color: '#666',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis' 
                  }}>
                    {option.name}
                  </span>
                </div>
              </Checkbox>
            </div>
          ))}
          {filteredOptions.length === 0 && (
            <div style={{ padding: '8px 12px', color: '#999', textAlign: 'center' }}>
              No options found
            </div>
          )}
        </div>
      </div>
    );
  };

  // Render destination filter dropdown for group-based filter
  const renderDestDropdown = (filterId) => {
    const currentFilter = groupFilters[filterId] || { destFilter: { mode: 'include', airports: [] } };

    // Filter options based on search text
    const filteredOptions = groupFilterOptions.destOptions.filter(option => 
      option.code.toLowerCase().includes(destSearchText.toLowerCase()) ||
      option.name.toLowerCase().includes(destSearchText.toLowerCase())
    );

    return (
      <div style={{ 
        backgroundColor: 'white', 
        boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
        borderRadius: '8px',
        padding: '8px 0',
        width: '450px'
      }}>
        <div style={{ padding: '4px 12px 8px', borderBottom: '1px solid #f0f0f0' }}>
          <Radio.Group
            value={currentFilter.destFilter.mode}
            onChange={e => setGroupFilters(prev => ({
              ...prev,
              [filterId]: {
                ...prev[filterId],
                destFilter: {
                  ...prev[filterId].destFilter,
                  mode: e.target.value
                }
              }
            }))}
            style={{ display: 'flex', gap: '8px' }}
          >
            <Radio.Button 
              value="include" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Include
            </Radio.Button>
            <Radio.Button 
              value="exclude" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Exclude
            </Radio.Button>
          </Radio.Group>
        </div>
        <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
          <Input
            placeholder="Search destination airports/groups..."
            value={destSearchText}
            onChange={e => setDestSearchText(e.target.value)}
            size="small"
            allowClear
            onClick={e => e.stopPropagation()}
          />
        </div>
        <div style={{ 
          maxHeight: '400px', 
          overflowY: 'auto',
          padding: '8px 0'
        }}>
          {filteredOptions.map(option => (
            <div 
              key={option.code} 
              style={{ 
                padding: '4px 12px',
                cursor: 'pointer'
              }}
            >
              <Checkbox
                checked={currentFilter.destFilter.airports.includes(option.code)}
                onChange={e => {
                  const isChecked = e.target.checked;
                  setGroupFilters(prev => ({
                    ...prev,
                    [filterId]: {
                      ...prev[filterId],
                      destFilter: {
                        ...prev[filterId].destFilter,
                        airports: isChecked 
                          ? [...prev[filterId].destFilter.airports, option.code]
                          : prev[filterId].destFilter.airports.filter(a => a !== option.code)
                      }
                    }
                  }));
                }}
              >
                <div style={{ display: 'flex', flexDirection: 'column', width: '390px' }}>
                  <span style={{ fontWeight: 500 }}>{option.code}</span>
                  <span style={{ 
                    fontSize: '12px', 
                    color: '#666',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis' 
                  }}>
                    {option.name}
                  </span>
                </div>
              </Checkbox>
            </div>
          ))}
          {filteredOptions.length === 0 && (
            <div style={{ padding: '8px 12px', color: '#999', textAlign: 'center' }}>
              No options found
            </div>
          )}
        </div>
      </div>
    );
  };

  // Simplified segment dropdown (no reordering, include only)
  const renderSegmentsDropdownSimple = (filterId) => {
    const currentFilter = segmentFilters[filterId] || { segments: [] };

    // Get filtered segments based on search text
    const filteredSegments = uniqueSegments.filter(segment => 
      segment.toLowerCase().includes(segmentSearchText.toLowerCase())
    );

    return (
      <div style={{ 
        backgroundColor: 'white', 
        boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
        borderRadius: '8px',
        padding: '8px 0',
        width: '320px'
      }}>
        <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
          <Input
            placeholder="Search segments..."
            value={segmentSearchText}
            onChange={e => setSegmentSearchText(e.target.value)}
            size="small"
            allowClear
            onClick={e => e.stopPropagation()}
          />
        </div>
        <div style={{ 
          maxHeight: '400px', 
          overflowY: 'auto',
          padding: '8px 0'
        }}>
          {filteredSegments.map(segment => (
            <div 
              key={segment} 
              style={{ 
                padding: '4px 12px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                backgroundColor: 'white',
                borderBottom: '1px solid #f9f9f9'
              }}
            >
              <Checkbox
                checked={currentFilter.segments.includes(segment)}
                onChange={e => {
                  const isChecked = e.target.checked;
                  setSegmentFilters(prev => ({
                    ...prev,
                    [filterId]: {
                      ...prev[filterId],
                      segments: isChecked 
                        ? [...prev[filterId].segments, segment]
                        : prev[filterId].segments.filter(s => s !== segment)
                    }
                  }));
                }}
                onClick={(e) => e.stopPropagation()}
              >
                {segment}
              </Checkbox>
            </div>
          ))}
          {filteredSegments.length === 0 && (
            <div style={{ padding: '8px 12px', color: '#999', textAlign: 'center' }}>
              No segments found
            </div>
          )}
        </div>
      </div>
    );
  };

  // Render class dropdown for group/segment filter
  const renderClassDropdownForFilter = (filterType, filterId) => {
    const currentFilter = filterType === 'group' 
      ? groupFilters[filterId]?.classFilter || []
      : segmentFilters[filterId]?.classFilter || [];

    const setFilterFn = filterType === 'group'
      ? (newValue) => setGroupFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            classFilter: newValue
          }
        }))
      : (newValue) => setSegmentFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            classFilter: newValue
          }
        }));

    const classOptions = [
      { value: 'Economy', label: 'Economy (Y)' },
      { value: 'Premium Economy', label: 'Premium Economy (W)' },
      { value: 'Business', label: 'Business (J)' },
      { value: 'First', label: 'First (F)' }
    ];

    return (
      <div style={{ 
        backgroundColor: 'white', 
        boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
        borderRadius: '8px',
        padding: '8px',
        width: '280px'
      }}>
        <div style={{ marginBottom: '8px', display: 'flex', justifyContent: 'space-between' }}>
          <span>Cabin Classes</span>
          <Button 
            type="link" 
            size="small" 
            onClick={() => setFilterFn([])}
            style={{ padding: 0 }}
          >
            Reset
          </Button>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {classOptions.map(option => (
            <Checkbox
              key={option.value}
              checked={currentFilter.includes(option.value)}
              onChange={e => {
                if (e.target.checked) {
                  setFilterFn([...currentFilter, option.value]);
                } else {
                  setFilterFn(currentFilter.filter(c => c !== option.value));
                }
              }}
            >
              {option.label}
            </Checkbox>
          ))}
        </div>
      </div>
    );
  };

  // Render sources dropdown for group/segment filter
  const renderSourcesDropdownForFilter = (filterType, filterId) => {
    const currentFilter = filterType === 'group' 
      ? groupFilters[filterId]?.sourceFilter || { mode: 'include', sources: [] }
      : segmentFilters[filterId]?.sourceFilter || { mode: 'include', sources: [] };

    const setFilterFn = filterType === 'group'
      ? (newValue) => setGroupFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            sourceFilter: newValue
          }
        }))
      : (newValue) => setSegmentFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            sourceFilter: newValue
          }
        }));

    // Filter sources based on search text
    const filteredSources = uniqueSources.filter(source => 
      source.code.toLowerCase().includes(sourceSearchText.toLowerCase()) ||
      source.name.toLowerCase().includes(sourceSearchText.toLowerCase())
    );

    return (
      <div style={{ 
        backgroundColor: 'white', 
        boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
        borderRadius: '8px',
        padding: '8px 0',
        width: '320px'
      }}>
        <div style={{ padding: '4px 12px 8px', borderBottom: '1px solid #f0f0f0', marginBottom: '8px' }}>
          <Radio.Group
            value={currentFilter.mode}
            onChange={e => setFilterFn({
              ...currentFilter,
              mode: e.target.value
            })}
            style={{ display: 'flex', gap: '8px' }}
          >
            <Radio.Button 
              value="include" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Include
            </Radio.Button>
            <Radio.Button 
              value="exclude" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Exclude
            </Radio.Button>
          </Radio.Group>
        </div>

        <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
          <Input
            placeholder="Search sources..."
            value={sourceSearchText}
            onChange={e => setSourceSearchText(e.target.value)}
            size="small"
            allowClear
            onClick={e => e.stopPropagation()}
          />
        </div>

        <div style={{ 
          maxHeight: '400px', 
          overflowY: 'auto',
          padding: '8px 0'
        }}>
          <div style={{ marginBottom: '8px', display: 'flex', justifyContent: 'flex-end', padding: '0 12px' }}>
            <Button 
              type="link" 
              size="small" 
              onClick={() => setFilterFn({ ...currentFilter, sources: [] })}
              style={{ padding: 0 }}
            >
              Reset
            </Button>
          </div>

          {filteredSources.map(source => (
            <div 
              key={source.code} 
              style={{ 
                padding: '4px 12px',
                cursor: 'pointer'
              }}
            >
              <Checkbox
                checked={currentFilter.sources.includes(source.code)}
                onChange={e => {
                  const isChecked = e.target.checked;
                  setFilterFn({
                    ...currentFilter,
                    sources: isChecked 
                      ? [...currentFilter.sources, source.code]
                      : currentFilter.sources.filter(s => s !== source.code)
                  });
                }}
              >
                <div style={{ display: 'flex', flexDirection: 'column' }}>
                  <span style={{ fontWeight: 500 }}>{source.code}</span>
                  <span style={{ 
                    fontSize: '12px', 
                    color: '#666',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    maxWidth: '260px'
                  }}>
                    {source.name}
                  </span>
                </div>
              </Checkbox>
            </div>
          ))}

          {filteredSources.length === 0 && (
            <div style={{ padding: '8px 12px', color: '#999', textAlign: 'center' }}>
              No sources found
            </div>
          )}
        </div>
      </div>
    );
  };

  // Render airlines dropdown for group/segment filter
  const renderAirlinesDropdownForFilter = (filterType, filterId) => {
    const currentFilter = filterType === 'group' 
      ? groupFilters[filterId]?.airlinesFilter || { mode: 'include', airlines: [] }
      : segmentFilters[filterId]?.airlinesFilter || { mode: 'include', airlines: [] };

    const setFilterFn = filterType === 'group'
      ? (newValue) => setGroupFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            airlinesFilter: newValue
          }
        }))
      : (newValue) => setSegmentFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            airlinesFilter: newValue
          }
        }));

    // Filter airlines based on search text
    const filteredAirlines = uniqueAirlines.filter(airline => 
      airline.code.toLowerCase().includes(airlinesSearchText.toLowerCase()) ||
      airline.name.toLowerCase().includes(airlinesSearchText.toLowerCase())
    );

    return (
      <div style={{ 
        backgroundColor: 'white', 
        boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
        borderRadius: '8px',
        padding: '8px 0',
        width: '320px'
      }}>
        <div style={{ padding: '4px 12px 8px', borderBottom: '1px solid #f0f0f0', marginBottom: '8px' }}>
          <Radio.Group
            value={currentFilter.mode}
            onChange={e => setFilterFn({
              ...currentFilter,
              mode: e.target.value
            })}
            style={{ display: 'flex', gap: '8px' }}
          >
            <Radio.Button 
              value="include" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Include
            </Radio.Button>
            <Radio.Button 
              value="exclude" 
              style={{ flex: 1, textAlign: 'center' }}
            >
              Exclude
            </Radio.Button>
          </Radio.Group>
        </div>

        <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f0f0' }}>
          <Input
            placeholder="Search airlines..."
            value={airlinesSearchText}
            onChange={e => setAirlinesSearchText(e.target.value)}
            size="small"
            allowClear
            onClick={e => e.stopPropagation()}
          />
        </div>

        <div style={{ 
          maxHeight: '400px', 
          overflowY: 'auto',
          padding: '8px 0'
        }}>
          <div style={{ marginBottom: '8px', display: 'flex', justifyContent: 'flex-end', padding: '0 12px' }}>
            <Button 
              type="link" 
              size="small" 
              onClick={() => setFilterFn({ ...currentFilter, airlines: [] })}
              style={{ padding: 0 }}
            >
              Reset
            </Button>
          </div>

          {filteredAirlines.map(airline => (
            <div 
              key={airline.code} 
              style={{ 
                padding: '4px 12px',
                cursor: 'pointer'
              }}
            >
              <Checkbox
                checked={currentFilter.airlines.includes(airline.code)}
                onChange={e => {
                  const isChecked = e.target.checked;
                  setFilterFn({
                    ...currentFilter,
                    airlines: isChecked 
                      ? [...currentFilter.airlines, airline.code]
                      : currentFilter.airlines.filter(a => a !== airline.code)
                  });
                }}
              >
                <div style={{ display: 'flex', flexDirection: 'column' }}>
                  <span style={{ fontWeight: 500 }}>{airline.code}</span>
                  <span style={{ 
                    fontSize: '12px', 
                    color: '#666',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    maxWidth: '260px'
                  }}>
                    {airline.name}
                  </span>
                </div>
              </Checkbox>
            </div>
          ))}

          {filteredAirlines.length === 0 && (
            <div style={{ padding: '8px 12px', color: '#999', textAlign: 'center' }}>
              No airlines found
            </div>
          )}
        </div>
      </div>
    );
  };

  // Render points dropdown for group/segment filter
  const renderPointsDropdownForFilter = (filterType, filterId) => {
    const currentFilter = filterType === 'group' 
      ? groupFilters[filterId]?.pointsFilter || null
      : segmentFilters[filterId]?.pointsFilter || null;

    const setFilterFn = filterType === 'group'
      ? (newValue) => setGroupFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            pointsFilter: newValue
          }
        }))
      : (newValue) => setSegmentFilters(prev => ({
          ...prev,
          [filterId]: {
            ...prev[filterId],
            pointsFilter: newValue
          }
        }));

    // Calculate min/max points from all available flights
    const [min, max] = pointsRange;

    return (
      <div style={{ 
        backgroundColor: 'white', 
        boxShadow: '0 3px 6px -4px rgba(0,0,0,.12), 0 6px 16px 0 rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05)',
        borderRadius: '8px',
        padding: '12px 16px',
        width: '320px'
      }}>
        <div style={{ marginBottom: '16px' }}>
          <div style={{ marginBottom: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span>Points Range</span>
            <Button 
              type="link" 
              size="small" 
              onClick={() => setFilterFn(null)}
              style={{ padding: 0 }}
            >
              Reset
            </Button>
          </div>
          <div style={{ 
            display: 'flex', 
            gap: '8px', 
            alignItems: 'center',
            marginBottom: '12px'
          }}>
            <Input
              value={currentFilter ? currentFilter[0].toLocaleString() : min.toLocaleString()}
              disabled
              style={{ width: '100px', textAlign: 'center' }}
              size="small"
            />
            <span>to</span>
            <Input
              value={currentFilter ? currentFilter[1].toLocaleString() : max.toLocaleString()}
              disabled
              style={{ width: '100px', textAlign: 'center' }}
              size="small"
            />
          </div>
          <Slider
            range
            min={min}
            max={max}
            step={1000}
            value={currentFilter || [min, max]}
            onChange={value => setFilterFn(value)}
            tipFormatter={value => value.toLocaleString()}
          />
        </div>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', gap: '2px' }}>
      {classesToShow.map(classCode => {
        const isAvailable = shouldShowAsAvailable(classCode);
        const isDirect = classes[`${classCode}Direct`];
        const sources = getSourcesForClass(classCode);
        const flights = getFlightsForClass(classCode);

        return (
          <div
            key={classCode}
            title={!isAvailable ? "Not Available" : undefined}
            style={{
              backgroundColor: getBackgroundColor(classCode, isAvailable),
              color: isAvailable ? '#684634' : '#999',
              padding: '0px 4px',
              borderRadius: '4px',
              fontSize: '13px',
              fontFamily: 'Menlo',
              width: '20px',
              textAlign: 'center',
              position: 'relative',
              cursor: isAvailable ? 'pointer' : 'default'
            }}
            onMouseEnter={(e) => {
              if (isAvailable && flights.length > 0) {
                const tooltipId = `tooltip-${route}-${classCode}-${date}`;

                // Remove any existing tooltip with the same ID
                const existingTooltip = document.getElementById(tooltipId);
                if (existingTooltip) {
                  document.body.removeChild(existingTooltip);
                }

                // Also remove any other active tooltips
                if (activeTooltipRef.current && activeTooltipRef.current !== tooltipId) {
                  const oldTooltip = document.getElementById(activeTooltipRef.current);
                  if (oldTooltip) {
                    document.body.removeChild(oldTooltip);
                  }
                }

                // Save current tooltip ID as active
                activeTooltipRef.current = tooltipId;

                // Create and populate the tooltip element
                const tooltip = createEnhancedTooltip(classCode, flights);
                tooltip.id = tooltipId;
                tooltip.style.position = 'fixed'; // Changed from absolute to fixed for better positioning
                tooltip.style.zIndex = '1000';
                tooltip.style.opacity = '0'; // Start invisible for smooth fade-in

                // Add tooltip to the document body to get its dimensions
                document.body.appendChild(tooltip);

                // Calculate optimal position to ensure tooltip stays within viewport
                const tooltipRect = tooltip.getBoundingClientRect();
                const viewportWidth = window.innerWidth;
                const viewportHeight = window.innerHeight;

                // Calculate initial position (10px offset from cursor)
                let left = e.clientX + 10;
                let top = e.clientY + 10;

                // Adjust horizontal position if tooltip would overflow right edge
                if (left + tooltipRect.width > viewportWidth - 20) {
                  left = Math.max(20, e.clientX - tooltipRect.width - 10);
                }

                // Adjust vertical position if tooltip would overflow bottom edge
                if (top + tooltipRect.height > viewportHeight - 20) {
                  top = Math.max(20, viewportHeight - tooltipRect.height - 20);
                }

                // Apply calculated position
                tooltip.style.left = `${left}px`;
                tooltip.style.top = `${top}px`;

                // Fade in the tooltip
                setTimeout(() => {
                  tooltip.style.opacity = '1';
                }, 10);
              }
            }}
            onMouseLeave={() => {
              const tooltipId = `tooltip-${route}-${classCode}-${date}`;
              const tooltip = document.getElementById(tooltipId);

              if (tooltip) {
                // Fade out and then remove tooltip
                tooltip.style.opacity = '0';
                setTimeout(() => {
                  if (tooltip.parentNode) {
                document.body.removeChild(tooltip);
                  }
                  if (activeTooltipRef.current === tooltipId) {
                    activeTooltipRef.current = null;
                  }
                }, 200);
              }
            }}
          >
            {isAvailable ? classCode : '-'}
            {isAvailable && !isDirect && (
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background: 'repeating-linear-gradient(45deg, transparent, transparent 3px, rgba(255,255,255,0.7) 3px, rgba(255,255,255,0.7) 6px)',
                  pointerEvents: 'none'
                }}
              />
            )}
          </div>
        );
      })}
    </div>
  );
};

export default NormalFlightAvailabilityCalendar;
